using Anthropic;
using Anthropic.Models.Messages;

AnthropicClient client = new();
List<MessageParam> messages = [new() { Role = Role.User, Content = "Why was order 4412 refunded twice?" }];

while (true)
{
    var response = await client.Messages.Create(new MessageCreateParams
    {
        Model = "claude-opus-5-5",
        MaxTokens = 16000,
        Tools = Tools,          // your tool definitions
        Messages = messages,
    });
    // Keep Claude's full reply (text + tool_use blocks) in history
    // (C# has no .ToParam(); ToParams rebuilds each block as its *Param type)
    messages.Add(new() { Role = Role.Assistant, Content = ToParams(response.Content) });

    if (response.StopReason == "end_turn")
        break;                  // Claude says the turn is finished

    if (response.StopReason == "tool_use")
    {
        List<ContentBlockParam> results = [];
        foreach (var block in response.Content)
            if (block.TryPickToolUse(out ToolUseBlock? toolUse))
            {
                string output = RunTool(toolUse.Name, toolUse.Input);
                results.Add(new ToolResultBlockParam { ToolUseID = toolUse.ID,
                                                       Content = output });
            }
        // All results go back in ONE user message
        messages.Add(new() { Role = Role.User, Content = results });
    }
}

