import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();
const messages: Anthropic.MessageParam[] = [
  { role: "user", content: "Why was order 4412 refunded twice?" },
];

while (true) {
  const response = await client.messages.create({
    model: "claude-opus-5-5",
    max_tokens: 16000,
    tools: TOOLS,            // your tool definitions
    messages,
  });
  // Keep Claude's full reply (text + tool_use blocks) in history
  messages.push({ role: "assistant", content: response.content });

  if (response.stop_reason === "end_turn") {
    break;                   // Claude says the turn is finished
  }

  if (response.stop_reason === "tool_use") {
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type === "tool_use") {
        const output = runTool(block.name, block.input);
        results.push({ type: "tool_result",
                       tool_use_id: block.id,
                       content: output });
      }
    }
    // All results go back in ONE user message
    messages.push({ role: "user", content: results });
  }
}

