from claude_agent_sdk import ClaudeAgentOptions, HookMatcher

async def refund_limit(input_data, tool_use_id, context):
    amount = input_data["tool_input"].get("amount", 0)
    if amount > 500:
        return {"hookSpecificOutput": {
            "hookEventName": input_data["hook_event_name"],
            "permissionDecision": "deny",
            "permissionDecisionReason":
                "Refunds over $500 need a human. Call escalate_to_human.",
        }}
    return {}  # allow

async def normalise_dates(input_data, tool_use_id, context):
    # Rewrite Unix timestamps / status codes into ISO 8601 and named
    # statuses, then replace the result Claude will read
    clean = normalise(input_data["tool_response"])   # your own helper
    return {"hookSpecificOutput": {
        "hookEventName": input_data["hook_event_name"],
        "updatedToolOutput": clean,
    }}

options = ClaudeAgentOptions(hooks={
    "PreToolUse":  [HookMatcher(matcher="mcp__billing__process_refund",
                                hooks=[refund_limit])],
    "PostToolUse": [HookMatcher(matcher="mcp__orders__.*",
                                hooks=[normalise_dates])],
})

