const refundLimit: HookCallback = async (inputData, toolUseId, context) => {
  const amount = (inputData as any).tool_input.amount ?? 0;
  if (amount > 500) {
    return { hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
      permissionDecisionReason:
        "Refunds over $500 need a human. Call escalate_to_human.",
    }};
  }
  return {};  // allow
};

const normaliseDates: HookCallback = async (inputData, toolUseId, context) => {
  // Rewrite Unix timestamps / status codes into ISO 8601 and named
  // statuses, then replace the result Claude will read
  const clean = normalise((inputData as any).tool_response);   // your own helper
  return { hookSpecificOutput: {
    hookEventName: "PostToolUse",
    updatedToolOutput: clean,
  }};
};

const options: Options = { hooks: {
  PreToolUse:  [{ matcher: "mcp__billing__process_refund",
                  hooks: [refundLimit] }],
  PostToolUse: [{ matcher: "mcp__orders__.*",
                  hooks: [normaliseDates] }],
}};

