const ASPECTS = ["security", "error handling", "performance"];   // always the same

function reviewPr(changedFiles: ChangedFile[], diff: string): Finding[] {
  const findings: Finding[] = [];
  // 1) Per-file local passes (can run in parallel)
  for (const f of changedFiles) {
    for (const aspect of ASPECTS) {                       // fixed chain
      findings.push(...askClaude(
        `Review ONLY ${f.path} for ${aspect}.\n${f.content}`));
    }
  }

  // 2) Separate cross-file integration pass
  const summary = summariseInterfaces(changedFiles);  // signatures, exports, calls
  findings.push(...askClaude(
    "Given these interface changes across files, find mismatches: " +
    "renamed functions, changed contracts, broken callers.\n" + summary));
  return findings;
}

